@layer nz.tokens, nz.themes, nz.reset, nz.base, nz.components, nz.patterns, nz.utilities;

/* @nizivo/react/css/inline.css. data-gap sets ONLY the private; the public --nz-inline-gap hook is read
   once, at the property, and never assigned here. */
@layer nz.components {
  .nz-inline {
    --_nz-inline-gap: 0;

    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: var(--nz-inline-gap, var(--_nz-inline-gap));
  }

  .nz-inline[data-gap='0'] {
    --_nz-inline-gap: var(--nz-space-0);
  }

  .nz-inline[data-gap='0-5'] {
    --_nz-inline-gap: var(--nz-space-0-5);
  }

  .nz-inline[data-gap='1'] {
    --_nz-inline-gap: var(--nz-space-1);
  }

  .nz-inline[data-gap='1-5'] {
    --_nz-inline-gap: var(--nz-space-1-5);
  }

  .nz-inline[data-gap='2'] {
    --_nz-inline-gap: var(--nz-space-2);
  }

  .nz-inline[data-gap='3'] {
    --_nz-inline-gap: var(--nz-space-3);
  }

  .nz-inline[data-gap='4'] {
    --_nz-inline-gap: var(--nz-space-4);
  }

  .nz-inline[data-gap='5'] {
    --_nz-inline-gap: var(--nz-space-5);
  }

  .nz-inline[data-gap='6'] {
    --_nz-inline-gap: var(--nz-space-6);
  }

  .nz-inline[data-gap='8'] {
    --_nz-inline-gap: var(--nz-space-8);
  }

  .nz-inline[data-gap='10'] {
    --_nz-inline-gap: var(--nz-space-10);
  }

  .nz-inline[data-gap='12'] {
    --_nz-inline-gap: var(--nz-space-12);
  }

  .nz-inline[data-gap='16'] {
    --_nz-inline-gap: var(--nz-space-16);
  }

  .nz-inline[data-gap='20'] {
    --_nz-inline-gap: var(--nz-space-20);
  }

  .nz-inline[data-gap='24'] {
    --_nz-inline-gap: var(--nz-space-24);
  }
}
